<script>
	const ROWS = 300;

	let executions = 0;

	class Session {
		data = $state({ version: 0 });
		index = $derived.by(() => {
			executions += 1;
			return new Map([['v', this.data.version]]); // fresh object => !equals
		});
		list = $derived.by(() => [...this.index.values()]);
		read(i) {
			return this.list[0] + i;
